final class Format
{
	private Format()
	{
	}

	/**
	 * @return e.g. "+1,234 gp" or "-56 gp"
	 */
	static String gp(long value)
	{
		return (value > 0 ? "+" : "") + QuantityFormatter.formatNumber(value) + " gp";
	}

	/**
	 * @return a shortened amount for tight spaces, e.g. "+123K gp" or "-1.23M gp"
	 */
	static String gpShort(long value)
	{
		return (value > 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(value) + " gp";
	}

	/**
	 * @return profit per point of Magic xp for a High Alchemy cast, e.g. "+2.5 gp/xp"
	 */
	static String gpPerXp(long profitPerCast)
	{
		return String.format("%+.1f gp/xp", (double) profitPerCast / ProfitCalculator.HIGH_ALCH_XP);
	}

	static Color profitColor(long value)
	{
		if (value > 0)
		{
			return ColorScheme.PROGRESS_COMPLETE_COLOR;
		}
		if (value < 0)
		{
			return ColorScheme.PROGRESS_ERROR_COLOR;
		}
		return Color.WHITE;
	}
}

package com.alchledger;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import javax.inject.Singleton;
import net.runelite.api.Item;

/**
 * Quantities of items in the inventory and bank, keyed by canonical item id.
 */
@Singleton
public class OwnedItems
{
	private Map<Integer, Long> inventory = new HashMap<>();
	private Map<Integer, Long> bank = new HashMap<>();
	private boolean bankSeen;

	public synchronized void setInventory(Map<Integer, Long> items)
	{
		inventory = items;
	}

	public synchronized void setBank(Map<Integer, Long> items)
	{
		bank = items;
		bankSeen = true;
	}

	public synchronized boolean isBankSeen()
	{
		return bankSeen;
	}

	public synchronized Map<Integer, Long> getInventory()
	{
		return new HashMap<>(inventory);
	}

	public synchronized Map<Integer, Long> getBank()
	{
		return new HashMap<>(bank);
	}

	public synchronized void clear()
	{
		inventory = new HashMap<>();
		bank = new HashMap<>();
		bankSeen = false;
	}

	public static Map<Integer, Long> count(Item[] items, IntUnaryOperator canonicalize)
	{
		Map<Integer, Long> counts = new HashMap<>();
		for (Item item : items)
		{
			if (item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			counts.merge(canonicalize.applyAsInt(item.getId()), (long) item.getQuantity(), Long::sum);
		}
		return counts;
	}
}

package com.alchledger;

import java.awt.Color;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Works out the profit of high alching an item. Must be used on the client thread.
 */
@Singleton
public class ProfitCalculator
{
	public static final int HIGH_ALCH_XP = 65;

	private static final int UNKNOWN = Integer.MIN_VALUE;

	private final ItemManager itemManager;
	private final AlchLedgerConfig config;

	// Keyed by the raw item id, so overlays can look up without canonicalising every frame
	private final Map<Integer, Integer> cache = new ConcurrentHashMap<>();

	private volatile boolean ironmanDetected;

	@Inject
	ProfitCalculator(ItemManager itemManager, AlchLedgerConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
	}

	public void clearCache()
	{
		cache.clear();
	}

	public void setIronmanDetected(boolean ironmanDetected)
	{
		this.ironmanDetected = ironmanDetected;
	}

	public boolean isIronman()
	{
		switch (config.accountMode())
		{
			case STANDARD:
				return false;
			case IRONMAN:
				return true;
			default:
				return ironmanDetected;
		}
	}

	public int getNatureRunePrice()
	{
		if (config.useLiveNatureRunePrice())
		{
			int live = (int) itemManager.getItemPrice(ItemID.NATURERUNE);
			if (live > 0)
			{
				return live;
			}
		}
		return config.natureRunePrice();
	}

	/**
	 * @return the profit per cast in the current account mode, or null if it is unknown
	 */
	public Integer getProfit(int itemId)
	{
		int profit = cache.computeIfAbsent(itemId, this::computeProfit);
		return profit == UNKNOWN ? null : profit;
	}

	private int computeProfit(int itemId)
	{
		int id = itemManager.canonicalize(itemId);
		if (isCurrency(id))
		{
			return UNKNOWN;
		}

		int alchValue = itemManager.getItemComposition(id).getHaPrice();
		if (alchValue <= 0)
		{
			return UNKNOWN;
		}

		if (isIronman())
		{
			return alchValue - getNatureRunePrice();
		}

		int gePrice = (int) itemManager.getItemPrice(id);
		if (gePrice <= 0)
		{
			return UNKNOWN;
		}
		return alchValue - gePrice - getNatureRunePrice();
	}

	public static boolean isCurrency(int canonicalId)
	{
		return canonicalId == ItemID.COINS || canonicalId == ItemID.PLATINUM;
	}

	public ProfitTier getTier(int profit)
	{
		if (profit >= config.highThreshold())
		{
			return ProfitTier.HIGH;
		}
		if (profit >= config.mediumThreshold())
		{
			return ProfitTier.MEDIUM;
		}
		if (profit >= config.lowThreshold())
		{
			return ProfitTier.LOW;
		}
		return ProfitTier.BELOW_LOW;
	}

	public Color getColor(ProfitTier tier)
	{
		if (tier == null)
		{
			return null;
		}
		switch (tier)
		{
			case BELOW_LOW:
				return config.lossColor();
			case LOW:
				return config.lowColor();
			case MEDIUM:
				return config.mediumColor();
			case HIGH:
				return config.highColor();
			default:
				return null;
		}
	}
}

package com.alchledger;

public enum ProfitTier
{
	// Anything under the low threshold, including losses
	BELOW_LOW,
	LOW,
	MEDIUM,
	HIGH
}

package com.alchledger;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Session and all-time alching profit. The all-time totals are saved per account.
 */
@Singleton
public class ProfitTracker
{
	private static final String ALL_TIME_PROFIT_KEY = "allTimeProfit";
	private static final String ALL_TIME_CASTS_KEY = "allTimeCasts";
	private static final int MAX_RECENT = 200;
	private static final Duration MIN_RATE_DURATION = Duration.ofMinutes(1);
	private static final Duration RATE_UPDATE_INTERVAL = Duration.ofSeconds(10);

	private final ConfigManager configManager;

	private final Deque<AlchRecord> recent = new ArrayDeque<>();
	private long sessionProfit;
	private int sessionCasts;
	private Instant sessionStart;
	private long allTimeProfit;
	private long allTimeCasts;
	private long sessionXp;
	// Hourly rates are only recalculated every few seconds so they don't flicker
	private Long profitPerHour;
	private Long xpPerHour;
	private Instant ratesUpdated;

	@Inject
	ProfitTracker(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public synchronized void loadAllTime()
	{
		allTimeProfit = parseLong(configManager.getRSProfileConfiguration(AlchLedgerConfig.GROUP, ALL_TIME_PROFIT_KEY));
		allTimeCasts = parseLong(configManager.getRSProfileConfiguration(AlchLedgerConfig.GROUP, ALL_TIME_CASTS_KEY));
	}

	public synchronized void record(AlchRecord record)
	{
		if (sessionStart == null)
		{
			sessionStart = record.getTime();
		}
		sessionProfit += record.getProfit();
		sessionXp += record.getXp();
		sessionCasts++;
		allTimeProfit += record.getProfit();
		allTimeCasts++;

		recent.addFirst(record);
		while (recent.size() > MAX_RECENT)
		{
			recent.removeLast();
		}

		saveAllTime();
	}

	public synchronized void resetSession()
	{
		sessionProfit = 0;
		sessionCasts = 0;
		sessionXp = 0;
		sessionStart = null;
		profitPerHour = null;
		xpPerHour = null;
		ratesUpdated = null;
		recent.clear();
	}

	public synchronized void resetAllTime()
	{
		allTimeProfit = 0;
		allTimeCasts = 0;
		saveAllTime();
	}

	public synchronized long getSessionProfit()
	{
		return sessionProfit;
	}

	public synchronized int getSessionCasts()
	{
		return sessionCasts;
	}

	public synchronized long getSessionXp()
	{
		return sessionXp;
	}

	public synchronized long getAllTimeProfit()
	{
		return allTimeProfit;
	}

	public synchronized long getAllTimeCasts()
	{
		return allTimeCasts;
	}

	/**
	 * @return profit per hour since the first cast, or null until a minute has passed
	 */
	public synchronized Long getProfitPerHour()
	{
		updateRates();
		return profitPerHour;
	}

	/**
	 * @return xp per hour since the first cast, or null until a minute has passed
	 */
	public synchronized Long getXpPerHour()
	{
		updateRates();
		return xpPerHour;
	}

	/**
	 * Recalculates the hourly rates, at most every {@link #RATE_UPDATE_INTERVAL}.
	 */
	private void updateRates()
	{
		Instant now = Instant.now();
		if (sessionStart == null
			|| (ratesUpdated != null && Duration.between(ratesUpdated, now).compareTo(RATE_UPDATE_INTERVAL) < 0))
		{
			return;
		}

		Duration elapsed = Duration.between(sessionStart, now);
		if (elapsed.compareTo(MIN_RATE_DURATION) < 0)
		{
			return;
		}

		double hours = elapsed.toMillis() / 3_600_000.0;
		profitPerHour = (long) (sessionProfit / hours);
		xpPerHour = (long) (sessionXp / hours);
		ratesUpdated = now;
	}

	/**
	 * @return the recent casts, newest first
	 */
	public synchronized List<AlchRecord> getRecent()
	{
		return new ArrayList<>(recent);
	}

	private void saveAllTime()
	{
		configManager.setRSProfileConfiguration(AlchLedgerConfig.GROUP, ALL_TIME_PROFIT_KEY, allTimeProfit);
		configManager.setRSProfileConfiguration(AlchLedgerConfig.GROUP, ALL_TIME_CASTS_KEY, allTimeCasts);
	}

	private static long parseLong(String value)
	{
		if (value == null)
		{
			return 0;
		}
		try
		{
			return Long.parseLong(value);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

